const searchIssues = `-- name: SearchIssues :many
SELECT i.id, i.repo_id, i.number, i.kind, i.title, i.body, i.state, i.state_reason, i.locked, i.lock_reason, i.author_id, i.milestone_id, i.comment_count, i.closed_at, i.closed_by, i.edited_at, i.edited_by, i.created_at, i.updated_at FROM issues i
WHERE i.repo_id = $1 AND i.kind = $2
  AND ($3::text = '' OR i.state = $3::text)
  AND (cardinality($4::uuid[]) = 0 OR
       (SELECT count(*) FROM issue_labels il WHERE il.issue_id = i.id AND il.label_id = ANY($4::uuid[])) = cardinality($4::uuid[]))
  AND (CASE $5::text
         WHEN 'none' THEN i.milestone_id IS NULL
         WHEN 'any' THEN i.milestone_id IS NOT NULL
         WHEN 'id' THEN i.milestone_id = $6::uuid
         ELSE true END)
  AND (CASE $7::text
         WHEN 'none' THEN NOT EXISTS (SELECT 1 FROM issue_assignees a WHERE a.issue_id = i.id)
         WHEN 'any' THEN EXISTS (SELECT 1 FROM issue_assignees a WHERE a.issue_id = i.id)
         WHEN 'id' THEN EXISTS (SELECT 1 FROM issue_assignees a WHERE a.issue_id = i.id AND a.user_id = $8::uuid)
         ELSE true END)
  AND (NOT $9::boolean OR i.author_id = $10::uuid)
  AND (NOT $11::boolean OR EXISTS (
         SELECT 1 FROM issue_references r
         WHERE r.source_issue_id = i.id AND r.target_kind = 'user' AND r.target_user_id = $12::uuid))
  AND ($13::text = '' OR
       issue_search_vector(i.title, i.body) @@ websearch_to_tsquery('simple', $13::text) OR
       EXISTS (SELECT 1 FROM issue_comments c WHERE c.issue_id = i.id
               AND issue_comment_search_vector(c.body) @@ websearch_to_tsquery('simple', $13::text)))
ORDER BY
  CASE WHEN $14::text = 'relevance' THEN ts_rank(issue_search_vector(i.title, i.body), websearch_to_tsquery('simple', $13::text)) END DESC NULLS LAST,
  CASE WHEN $14::text = 'created' AND $15::boolean THEN i.created_at END ASC,
  CASE WHEN $14::text = 'created' AND NOT $15::boolean THEN i.created_at END DESC,
  CASE WHEN $14::text = 'updated' AND $15::boolean THEN i.updated_at END ASC,
  CASE WHEN $14::text = 'updated' AND NOT $15::boolean THEN i.updated_at END DESC,
  CASE WHEN $14::text = 'comments' AND $15::boolean THEN i.comment_count END ASC,
  CASE WHEN $14::text = 'comments' AND NOT $15::boolean THEN i.comment_count END DESC,
  i.number DESC
LIMIT $17 OFFSET $16
`

type SearchIssuesParams struct {
	RepoID        uuid.UUID
	Kind          string
	State         string
	LabelIds      []uuid.UUID
	MilestoneMode string
	MilestoneID   uuid.UUID
	AssigneeMode  string
	AssigneeID    uuid.UUID
	ByAuthor      bool
	AuthorID      uuid.UUID
	ByMention     bool
	MentionedID   uuid.UUID
	Query         string
	Sort          string
	Ascending     bool
	Off           int32
	Lim           int32
}

// Issues of a repository matching every given filter. Modes: milestone_mode
// and assignee_mode are ” (no filter), 'none', 'any' or 'id'. query is a
// websearch_to_tsquery text matched against title, body and comments.
// sort is created, updated, comments or relevance.
func (q *Queries) SearchIssues(ctx context.Context, arg SearchIssuesParams) ([]Issue, error) {
	rows, err := q.db.Query(ctx, searchIssues,
		arg.RepoID,
		arg.Kind,
		arg.State,
		arg.LabelIds,
		arg.MilestoneMode,
		arg.MilestoneID,
		arg.AssigneeMode,
		arg.AssigneeID,
		arg.ByAuthor,
		arg.AuthorID,
		arg.ByMention,
		arg.MentionedID,
		arg.Query,
		arg.Sort,
		arg.Ascending,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Issue{}
	for rows.Next() {
		var i Issue
		if err := rows.Scan(
			&i.ID,
			&i.RepoID,
			&i.Number,
			&i.Kind,
			&i.Title,
			&i.Body,
			&i.State,
			&i.StateReason,
			&i.Locked,
			&i.LockReason,
			&i.AuthorID,
			&i.MilestoneID,
			&i.CommentCount,
			&i.ClosedAt,
			&i.ClosedBy,
			&i.EditedAt,
			&i.EditedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

