const sumRepoIssueAttachmentBytes = `-- name: SumRepoIssueAttachmentBytes :one
SELECT COALESCE(sum(size), 0)::bigint FROM issue_attachments WHERE repo_id = $1
`

// Bytes held by the issue attachments of a repository (released from the
// owner quota when the repository is deleted).
func (q *Queries) SumRepoIssueAttachmentBytes(ctx context.Context, repoID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, sumRepoIssueAttachmentBytes, repoID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

